"""Winner-gated private full-model QKV source/graph transformation.

The parent G12 runner owns model/token/hidden/import/fusion/system validation.
No winner receipt enables an environment flag or edits the working model.
"""
from __future__ import annotations
import json
from pathlib import Path
from etx.frontends import hip_link
from etx.ir import Resource
from .protocol import require,sha256

QKV_TEMPLATE=r'''
// Source-bound private model intervention generated by columns.integration.
#ifndef FP
#include "examples/dsv2lite/fleet_shim.hip"
#endif
#include "examples/experiment_program/columns/kernels.hip"
extern "C" __device__ void etx_shared_model_qkv(const etx_ctx* c) {
 constexpr int B=ETX_COLUMN_MODEL_BATCH;
 __shared__ float staged[B*2048];
 __shared__ float one[B];
 fleet::Scratch& scratch=*reinterpret_cast<fleet::Scratch*>(c->lds);
 const int layer=c->cst[0],xcd=c->domain,worker=c->coord[1];
 float* q_output[B];float* kv_output[B];
 for(int b=0;b<B;++b) {
  const FleetParams* fp=&etx_fleet_const[b];
  fleet::TokenCtx tc{};tc.tok=fp->tok;tc.epoch=fp->epoch;tc.pos=fp->pos;tc.dump=fp->dump!=0;tc.trace=false;
  fleet::Activations& act=*const_cast<fleet::Activations*>(&fp->act);
  const float* src=layer==0?act.x[0]:act.x[1];
  fleet::stage_residual(fp->d,src,layer>=2?act.expert_out:nullptr,layer==0?nullptr:act.x[0],scratch.vec,xcd,worker,fp->rt.coherent_acts!=0);
  fleet::dump_layer(fp->d,act,layer-1,scratch.vec,xcd,worker,tc);
  fleet::rms_norm_lds(fp->d,fp->w.layer_norm_in[layer],scratch.vec,scratch.smem);
  for(int i=threadIdx.x;i<2048;i+=256)staged[b*2048+i]=scratch.vec[i];
  if(threadIdx.x==0)one[b]=1.f;
  q_output[b]=act.q;kv_output[b]=act.kv_a;
  __syncthreads();
 }
 const FleetParams* fp=&etx_fleet_const[0];
 ColumnsArgs a{};a.weights=fp->w.layer_qkv[layer];a.inputs=nullptr;a.outputs=nullptr;a.scales=one;
 a.N=3072;a.K=2048;a.ld=2048;a.workers=37;a.xcds=8;a.role=0;a.explicit_geometry=1;a.task_worker=worker;a.task_xcd=xcd;
 // The per-request output pointers preserve native allocations and canonical
 // consumers. No newly cached cross-XCD activation buffer is introduced.
 for(int b=0;b<B;++b)a.output_columns[b]=q_output[b];
 column_rows<B,2,4>(a,staged,3072);
 a.weights+=(int64_t)3072*2048;a.N=576;
 for(int b=0;b<B;++b)a.output_columns[b]=kv_output[b];
 column_rows<B,2,4>(a,staged,576);
 __builtin_amdgcn_s_waitcnt(0);__threadfence();__syncthreads();
}
'''

def transform_qkv_graph(graph,batch,source):
    require(batch in (2,4),'only registered B2/B4 model arms')
    layers=sorted({int(grid.name.split('_qkv_')[1]) for grid in graph.grids if '_qkv_' in grid.name and grid.name.startswith('r')})
    require(layers,'original frozen QKV grids absent')
    for layer in layers:
        grids=[graph.grid(f'r{r}_qkv_{layer}') for r in range(batch)]
        require(all(grid.grid==(8,37) and 'kvs' in grid.body.symbol for grid in grids),'only frozen K1 native QKV topology is admitted')
        ins={};outs={}
        for grid in grids:
            ins.update({k:v.text for k,v in grid.in_edges.items()});outs.update({k:v.text for k,v in grid.out_edges.items()})
        position=min(graph.grids.index(grid) for grid in grids)
        for grid in grids:graph.grids.remove(grid)
        graph.call_device(f'columns_qkv_{layer}',(8,37),hip_link(str(source),'etx_shared_model_qkv'),
                          resource=Resource(threads=256,vgpr=256,agpr=0,lds_bytes=24576),
                          args=[f'fleet{r}' for r in range(batch)],consts=(layer,),domain_map='xw->x',worker_map='xw->w',
                          in_edges=ins,out_edges=outs,duration_us=20.)
        graph.grids.insert(position,graph.grids.pop())
    return graph

def prepare(winner,out,*,batch,baseline_revision,role='qkv',local_validation=False):
    """Write source/graph artifacts; reject an unrelated winner or role expansion."""
    require(baseline_revision=='554133d744b4591c9cf87c68b6817df781137c9b','model baseline identity mismatch')
    if not local_validation:
        require(winner.get('record')=='G02' and winner.get('status')=='MICRO_PASS_BOTH_REGIMES','both readiness regimes must pass')
        require(winner.get('batch')==batch and winner.get('role')==role,'winner batch/role differs')
        require(winner.get('native_exact') is True and winner.get('resource_admitted') is True,'native correctness/resource gate missing')
    require(batch in (2,4),'registered B2/B4 native model only')
    require(role=='qkv','a QKV pass cannot silently enable shared-expert/routed integration')
    out=Path(out);require(not out.exists(),'private integration destination occupied');out.mkdir(parents=True)
    source=out/'shared_qkv.hip';source.write_text(f'#define ETX_COLUMN_MODEL_BATCH {batch}\n'+QKV_TEMPLATE)
    graph=out/'model.py'
    graph.write_text('from examples.dsv2lite.graph import bindings, runtime\nfrom examples.experiment_program.columns.integration import frozen_graph as original\n'
                     'from examples.experiment_program.columns.integration import transform_qkv_graph\n'
                     f'def build():\n    return transform_qkv_graph(original({batch}),{batch},{str(source.resolve())!r})\n')
    result={'record':'G02','batch':batch,'role':role,'baseline_revision':baseline_revision,
            'source':str(source),'graph':str(graph),'source_sha256':sha256(source),'graph_sha256':sha256(graph),
            'status':'REQUIRES_EXACT_TARGET_RESOURCE_AND_FULL_MODEL_GATES',
            'resource_note':'B-column staging adds LDS to the original scratch. The target compiler/residency gate must reject an unresident persistent grid; no LDS/residency waiver.',
            'production_flags_enabled':False,'local_validation':bool(local_validation),'timing_eligible':not local_validation}
    (out/'integration.json').write_text(json.dumps(result,indent=2)+'\n');return result

def transform_grouped_graph(graph,batch,source):
    """Move required producers ahead of joins; retain native worker assignments."""
    require(batch in (2,4),'only registered B2/B4 routed arms')
    graph.tensor('column_group',(16384,),role='runtime',bytes_per_elem=1)
    layers=sorted({int(grid.name.split('_gate_up_')[1]) for grid in graph.grids if '_gate_up_' in grid.name and grid.name.startswith('r')})
    require(layers,'frozen routed native grids absent')
    for layer in layers:
        ups=[graph.grid(f'r{r}_gate_up_{layer}') for r in range(batch)]
        downs=[graph.grid(f'r{r}_down_{layer}') for r in range(batch)]
        routers=[graph.grid(f'r{r}_router_{layer}') for r in range(batch)]
        require(all(grid.grid==(8,37) for grid in ups+downs),'native routed geometry mismatch')
        require(all(grid.body.symbol=='fleet_expert_down_cached' for grid in downs),'unreviewed native downstream lifetime')
        meta=f'E_column_metadata_{layer}';allup=f'E_column_allup_{layer}'
        graph.etensor(meta,(1,),wait_count=1);graph.etensor(allup,(1,),wait_count=batch*8*37)
        phase_names=('qkv','qabs','attn','merge','oproj','router','gate_up','down')
        layer_grids=[grid for grid in graph.grids if any(grid.name==f'r{r}_{phase}_{layer}' for phase in phase_names for r in range(batch))]
        prefix=[grid for grid in layer_grids if grid not in ups+downs]
        position=min(graph.grids.index(grid) for grid in layer_grids)
        for grid in layer_grids:graph.grids.remove(grid)
        graph.call_device(f'column_metadata_{layer}',(1,1),hip_link(str(source),'etx_group_metadata'),
                          resource=Resource(threads=256,vgpr=256,agpr=0,lds_bytes=24576),args=['column_group'],consts=(layer,),
                          domain_map='xy->(0)',worker_map='xy->(37)',
                          in_edges={f'r{r}_E_norm_{layer}':'*' for r in range(batch)},out_edges={meta:'xy->(0)'},duration_us=5.)
        metadata=graph.grids.pop()
        for r,grid in enumerate(ups):
            grid.body=hip_link(str(source),'etx_group_up');grid.args=[f'fleet{r}','column_group']
            grid.in_edges[meta]=__import__('etx.ir.edgemap',fromlist=['EdgeMap']).EdgeMap.parse('xw->(0)')
            grid.out_edges[allup]=__import__('etx.ir.edgemap',fromlist=['EdgeMap']).EdgeMap.parse('xw->(0)')
            grid.resource=Resource(threads=256,vgpr=256,agpr=0,lds_bytes=max(24576,batch*2048*4))
        for r,grid in enumerate(downs):
            grid.body=hip_link(str(source),'etx_group_down');grid.args=[f'fleet{r}','column_group']
            grid.in_edges[allup]=__import__('etx.ir.edgemap',fromlist=['EdgeMap']).EdgeMap.parse('xw->(0)')
            grid.resource=Resource(threads=256,vgpr=256,agpr=0,lds_bytes=max(24576,batch*2048*4))
        graph.grids[position:position]=prefix+[metadata]+ups+downs
    return graph

def patch_group_host(text):
    from .patch_capture import once
    text=once(text,'using namespace fleet;','#include "examples/experiment_program/columns/group_state.h"\nusing namespace fleet;')
    marker='      wall_total += step_wall_ms; step_ms.push_back(step_wall_ms);'
    check='''      int group_error=0;
      HIP_CHECK(hipMemcpy(&group_error,(char*)hst.args[etx_host::arg_index("column_group")]+offsetof(ColumnGroupState,abort),4,hipMemcpyDeviceToHost));
      if(group_error)die("grouped column native metadata/epoch/visibility/deadline failure");
'''
    return once(text,marker,check+marker)

def prepare_grouped(winner,out,*,batch,baseline_revision,host_source,local_validation=False):
    require(baseline_revision=='554133d744b4591c9cf87c68b6817df781137c9b','model baseline identity mismatch')
    if not local_validation:
        require(winner.get('record')=='G05' and winner.get('status')=='MICRO_PASS_BOTH_REGIMES','G05 real-mix readiness regimes must both pass')
        require(winner.get('batch')==batch and winner.get('native_exact') is True and winner.get('resource_admitted') is True,'G05 winner identity/correctness/resource mismatch')
        require(winner.get('role')=='gate_up_down' and winner.get('matched_up_down') is True,'both routed up/down roles must pass before changing both model bodies')
        require(winner.get('native_pick_coverage') is True and winner.get('singleton_fallback_passed') is True,'actual group identities/singleton gate missing')
    require(batch in (2,4),'registered B2/B4 native model only')
    out=Path(out);require(not out.exists(),'private integration destination occupied');out.mkdir(parents=True)
    source=out/'grouped.hip';source.write_text(f'#define ETX_COLUMN_MODEL_BATCH {batch}\n#include "examples/experiment_program/columns/group_model.hip"\n')
    host=out/'host.hip';host.write_text(patch_group_host(Path(host_source).read_text()))
    graph=out/'model.py';graph.write_text('from examples.dsv2lite.graph import bindings, runtime\nfrom examples.experiment_program.columns.integration import frozen_graph as original\n'
        'from examples.experiment_program.columns.integration import transform_grouped_graph\n'
        f'def build():\n    return transform_grouped_graph(original({batch}),{batch},{str(source.resolve())!r})\n')
    result={'record':'G05','batch':batch,'baseline_revision':baseline_revision,'source':str(source),'graph':str(graph),'host':str(host),
            'source_sha256':sha256(source),'graph_sha256':sha256(graph),'host_sha256':sha256(host),
            'status':'REQUIRES_EXACT_TARGET_RESOURCE_AND_FULL_MODEL_GATES','production_flags_enabled':False,'local_validation':bool(local_validation),'timing_eligible':not local_validation,
            'added_costs':'native selector/group metadata; all-router/all-up joins; exact singleton LDS ID/mix restoration; per-writing-worker group release/acquire; agent-scope cross-XCD output stores; source lifetime preserved',
            'claim_scope':'real-mix wholemodel validation required; no duplicated-group extrapolation'}
    (out/'integration.json').write_text(json.dumps(result,indent=2)+'\n');return result


def frozen_graph(batch):
    import os
    from examples.dsv2lite.graph import build
    old={k:v for k,v in os.environ.items() if k.startswith('ETX_DSV2_')}
    try:
        for key in old:os.environ.pop(key)
        os.environ.update(ETX_DSV2_COH='l1',ETX_DSV2_REQUESTS=str(batch),ETX_DSV2_COUPLE='none',ETX_DSV2_KVA='shared')
        return build(requests=batch,routing_cached=True)
    finally:
        for key in list(os.environ):
            if key.startswith('ETX_DSV2_'):os.environ.pop(key)
        os.environ.update(old)
